"""Build the file://-compatible local character browser from audited JSON sources."""
from pathlib import Path
import json
import hashlib

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
SOURCES = ["JOKER_OFFICIAL_VISUALS.json", "QUEEN_SHADOWS_OFFICIAL_VISUALS.json", "JOKER_PUBLICATION_SUPPLEMENT.json"]
payload = {name: json.loads((HERE / name).read_text(encoding="utf-8")) for name in SOURCES}
assets = []
seen = set()
for filename, manifest in payload.items():
    for record in manifest["assets"]:
        source_file = ROOT / record["path"]
        assert source_file.is_file(), source_file
        assert hashlib.sha256(source_file.read_bytes()).hexdigest() == record["sha256"], source_file
        if record["sha256"] in seen:
            continue
        seen.add(record["sha256"])
        row = dict(record)
        row["manifest"] = filename
        row["local"] = source_file.relative_to(HERE).as_posix()
        row["category"] = "gameplay_frame" if row.get("source_kind") == "community_gameplay_recording_of_game_cutscene" else ("mirror" if row.get("source_kind") == "official_publication_third_party_scan" else "official")
        row["mirror"] = row["category"] == "mirror"
        row["dimensions"] = row.get("dimensions", row.get("pixels"))
        row["page"] = row.get("source_page_url", row.get("source_page"))
        role = row["character"].lower()
        row["person"] = next(k for k in ["cope", "baxter", "tasha", "coster", "rex", "kate", "tewy", "toprak"] if k in role)
        assets.append(row)

people = [
    dict(id="rex", name="Rex", zh="玩家飞行员", team="Joker", hero="joker/m4-OK.jpg", note="白头盔、橙红飞翼与 REX 字样；遮阳镜和氧气面罩。", boundary="没有取得具名露脸人设。驾驶舱图由官方 M4 文章语境关联玩家；头盔特写中的持物人、Jan Cope 都不是玩家的脸。", priority="以遮面、背身或第一人称入镜。"),
    dict(id="cope", name="Jan Cope", zh="科普", team="Joker", hero="joker/cope-jp.webp", note="短暗发、飞行墨镜、橄榄飞行装与救生背心。", boundary="设定书无墨镜头像可补 Cope 表情；他的外貌不转移给继承称号的 Rex。", priority="官网模型确定造型；p.174 补侧脸和表情。"),
    dict(id="baxter", name="Ellington Baxter", zh="巴克斯特 · Professor", team="Joker", hero="joker/baxter-jp.webp", note="短平头、矩形眼镜、修整胡须、黑色飞行夹克。", boundary="黑夹克休息造型与橄榄飞行装分场；设定书背面是另一层服装状态。", priority="p.175 补脸部侧面、眼镜、背部与鞋。"),
    dict(id="tasha", name="Tasha Severskaya", zh="塔莎 · Anastasia", team="Joker", hero="joker/tasha-jp.webp", note="金色发根与粉色短发、银白夹克、粉表、白灰粉底鞋。", boundary="银白夹克与白色无袖上衣为不同穿着状态；概念头像的发量/脸部比例不能混成新定装。", priority="官网模型为主；p.176 补侧脸、表情、饰物和鞋。"),
    dict(id="coster", name="William Coster", zh="科斯特 · Noise", team="Joker", hero="joker/coster-jp.webp", note="长刘海、短胡、灰 T 恤、前臂纹身、腰系飞行装。", boundary="机库出勤有完整飞行装。设定页的短发变体不自动构成已核实的剧情阶段。", priority="p.177 补侧脸、表情、纹身与墨镜。"),
    dict(id="kate", name="Kate Evans", zh="凯特 · Queen Flight", team="Queen", hero="kate-evans/official-jp-full.webp", note="近黑发、齐刘海与低盘编发；黑上衣、白色贴扎与双身份牌。", boundary="休息与出勤装分开；贴扎/伤势变化未按每个任务核定。", priority="官网模型为主；p.178 补背发与服装。"),
    dict(id="tewy", name="Carmille Tewy", zh="卡米尔 · Moon 11", team="Sotoa", hero="carmille-tewy/official-jp-full.webp", note="白色军帽与礼服、墨镜、金饰、白手套与轮椅。", boundary="站立服装设计不证明该阶段能行走；M29 白压力袖与手套有实录核对，全套压力服与头盔正面未由这些帧确认。", priority="地面造型用官网与 p.182；终战右手用 M29 9:44 / 9:52 实录，不能套白礼服。"),
    dict(id="toprak", name="Girish Toprak", zh="托普拉克 · Shadow 22", team="Sotoa", hero="girish-toprak/official-jp-full.webp", note="银白后梳短发、细胡须、黑军帽与披风礼服、金饰。", boundary="帽檐阴影不能把银白发画成黑发；地面礼服不直接等于驾驶舱飞行装备。", priority="官网模型与 p.183 联合确定发色、侧脸及披风。"),
]
data = json.dumps({"people": people, "assets": assets, "sources": SOURCES}, ensure_ascii=False).replace("</", "<\\/")
html = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>八人形象参考 · Hortus Regis Alti</title>
<style>
:root{color-scheme:dark;--bg:#101b21;--panel:#1a2930;--ink:#eef0e9;--muted:#b3c2c5;--line:#3b4b50;--gold:#e0bc79;--mint:#91cdb8}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.65 "Segoe UI","Microsoft YaHei",sans-serif}a{color:var(--gold);text-underline-offset:3px}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--gold);outline-offset:4px}.wrap{max-width:1420px;margin:auto;padding:40px 32px}.eyebrow{color:var(--gold);letter-spacing:.14em;font-size:12px}h1{font-size:clamp(28px,4vw,46px);line-height:1.25;margin:12px 0 16px;font-weight:650}h2{font-size:26px;line-height:1.35;margin:0 0 10px}h3{margin:0;font-size:17px}p{margin:8px 0}.intro{max-width:900px;color:var(--muted)}.metrics{display:flex;gap:24px;margin-top:22px;color:var(--muted)}.metrics strong{font-size:24px;color:var(--ink);margin-right:6px}.boundary{border:1px solid #78633f;border-left:4px solid var(--gold);padding:14px 18px;background:#2c2b24;margin:28px 0}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0 18px;align-items:end}.field{display:grid;gap:5px;color:var(--muted);font-size:12px}.field input,.field select{height:43px;background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:8px 12px;min-width:180px}.field:first-child{flex:1}.field input{width:100%}.count{color:var(--muted);font-size:13px;margin-left:auto}.people{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.person{border:1px solid var(--line);border-radius:10px;overflow:hidden;background:var(--panel);text-align:left;padding:0;color:var(--ink);display:flex;flex-direction:column;transition:border-color .15s,transform .15s}.person:hover{border-color:var(--gold);transform:translateY(-2px)}.person[aria-pressed=true]{border:2px solid var(--gold)}.person img{width:100%;height:240px;object-fit:contain;display:block;background:radial-gradient(ellipse at 50% 35%,#33444d,#18242c)}.person[data-person=rex] img{object-fit:cover}.person .body{padding:15px 16px;flex:1}.minor{font-size:12px;color:var(--muted)}.person p{font-size:13px;color:var(--muted);margin:8px 0}.tag{display:inline-block;font-size:11px;border:1px solid var(--line);border-radius:20px;padding:2px 9px;color:var(--mint);margin-bottom:8px}.tag.mirror{color:var(--gold);border-color:#74603e}.detail{margin-top:42px;padding-top:28px;border-top:1px solid var(--line);scroll-margin-top:20px}.detail-head{display:flex;gap:20px;justify-content:space-between;align-items:start}.detail-copy{max-width:850px}.use-note{color:var(--muted);font-size:14px}.guard{color:#e6d1a8;margin:14px 0 20px}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.asset{margin:0;border:1px solid var(--line);border-radius:9px;overflow:hidden;background:var(--panel);min-width:0}.asset .image-link{display:block;background:#27353d}.asset img{width:100%;height:350px;object-fit:contain;display:block}.asset figcaption{padding:16px}.asset h3{font-size:15px;overflow-wrap:anywhere}.asset .description{font-size:13px;color:var(--muted);margin:9px 0}.asset .links{display:flex;gap:15px;flex-wrap:wrap;font-size:13px}.asset details{font-size:12px;margin-top:12px;color:var(--muted)}.asset summary{cursor:pointer}.asset code{font-size:11px;overflow-wrap:anywhere;display:block;margin-top:5px}footer{border-top:1px solid var(--line);margin-top:42px;padding-top:20px;color:var(--muted);font-size:13px}.source-links{display:flex;gap:18px;flex-wrap:wrap}.empty{padding:24px;border:1px dashed var(--line);color:var(--muted)}@media(max-width:1000px){.people{grid-template-columns:repeat(2,minmax(0,1fr))}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.wrap{padding:26px 18px}.people{gap:10px}.person img{height:205px}.person .body{padding:12px}.person h3{font-size:15px}.person p{font-size:12px}.gallery{grid-template-columns:1fr}.asset img{height:380px}.metrics{gap:18px;flex-wrap:wrap}.detail-head{display:block}.field,.field:first-child{flex:1 1 100%}.field input,.field select{width:100%;min-width:0}.count{margin:0}.boundary{font-size:13px;padding:12px}.detail{margin-top:32px}h2{font-size:23px}}
</style></head><body><main class="wrap">
<div class="eyebrow">HORTUS REGIS ALTI · VISUAL REFERENCE</div><h1>八人形象参考</h1>
<p class="intro">Joker、Queen 与索托亚的人物图源。先看官网模型确定人物，再用设定书补充侧脸、表情与衣装结构；每张图保留原图、来源、尺寸与核对记录。</p>
<div class="metrics"><span><strong>8</strong>位人物</span><span><strong id="total">—</strong>份独立图像</span><span><strong>7</strong>页设定书镜像</span><span><strong>3</strong>帧游戏实录</span></div>
<div class="boundary"><strong>Rex 保持遮面。</strong>当前没有取得他的具名露脸人设；Cope 的脸、拿着 REX 头盔的人都不能替代玩家。设定书扫描来自第三方镜像，页面会单独标注。</div>
<div class="toolbar"><label class="field">查找人物<input id="search" type="search" placeholder="姓名、中文名或呼号" autocomplete="off"></label><label class="field">阵营<select id="team"><option value="">全部人物</option><option>Joker</option><option>Queen</option><option>Sotoa</option></select></label><span class="count" id="people-count" aria-live="polite"></span></div>
<section id="people" class="people" aria-label="人物选择"></section>
<section id="detail" class="detail" aria-label="选中人物参考"><div class="detail-head"><div class="detail-copy"><div class="eyebrow" id="detail-team"></div><h2 id="detail-name"></h2><p id="detail-note" class="use-note"></p><p id="detail-boundary" class="guard"></p></div><label class="field">图源范围<select id="source"><option value="all">全部图源</option><option value="official">官网直接托管</option><option value="mirror">设定书 · 第三方镜像</option><option value="gameplay_frame">游戏实录 · 非官方上传</option></select></label></div><p id="asset-count" class="minor" aria-live="polite"></p><div id="gallery" class="gallery"></div></section>
<footer><p>核对日期 2026-11-06 · 图片仅由本地 source-assets 读取，页面不请求远端图片或字体。浏览页由两份官方人物清单与独立出版物增补生成。</p><div class="source-links"><a href="JOKER_OFFICIAL_VISUALS.md">Joker 核对记录</a><a href="QUEEN_SHADOWS_OFFICIAL_VISUALS.md">Queen / Shadows 核对记录</a><a href="JOKER_PUBLICATION_SUPPLEMENT.md">Joker 设定书增补</a><a href="https://enso-order.acecombat.jp/character/" target="_blank" rel="noopener noreferrer">官方角色页 ↗</a></div><p>官网模型、出版物设计、游戏实录与剧情阶段分别记录。3 帧 M29 实录由用户提供的社区录像提取，不是官网发布。未核到开放再分发许可；原图作为本地参考，不把镜像标为官方服务器，也不把概念变体当成已核实剧情。</p></footer>
</main><script id="reference-data" type="application/json">__DATA__</script><script>
'use strict';const DATA=JSON.parse(document.getElementById('reference-data').textContent),$=id=>document.getElementById(id);let selected='rex';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function assetTitle(a){if(a.category==='gameplay_frame')return `M29 游戏实录 · ${Math.floor(a.time_seconds/60)}:${String(a.time_seconds%60).padStart(2,'0')}${a.time_seconds===600?' · 机首上下文':' · 压力手套'}`;if(a.mirror)return `《ACES at WAR 2029》· p.${a.printed_page}`;if(a.id?.endsWith('-jp')||a.source_kind==='official_website_character_render')return '官网全身造型';if(a.id?.endsWith('-us'))return '官网上身与面部';if(a.id?.includes('portrait-eu'))return '官网全身图 · 欧站';if(a.local.includes('helmet'))return '官方头盔 / 道具';if(a.id==='m4-OK')return '官方 M4 驾驶舱截图';if(a.id==='m4-COPE_OK')return 'Cope 甲板过场';if(a.id?.includes('thumbnail'))return '官方宣传封面';return '官网剧情 / 装备补充';}
function drawPeople(){const query=$('search').value.trim().toLowerCase(),team=$('team').value;const list=DATA.people.filter(p=>(!team||p.team===team)&&(!query||`${p.name} ${p.zh} ${p.team}`.toLowerCase().includes(query)));$('people-count').textContent=`显示 ${list.length} / 8 人`;$('people').innerHTML=list.length?list.map(p=>`<button class="person" type="button" data-person="${p.id}" aria-pressed="${selected===p.id}"><img src="source-assets/${p.hero}" alt="${esc(p.name)} 参考形象"><div class="body"><span class="tag">${p.team}</span><h3>${esc(p.name)}</h3><div class="minor">${esc(p.zh)}</div><p>${esc(p.note)}</p><div class="minor">查看 ${DATA.assets.filter(a=>a.person===p.id).length} 份资料 →</div></div></button>`).join(''):'<div class="empty">没有匹配人物。</div>';for(const b of document.querySelectorAll('.person'))b.addEventListener('click',()=>{selected=b.dataset.person;drawPeople();drawDetail();$('detail').scrollIntoView({behavior:'smooth'});});}
function drawDetail(){const p=DATA.people.find(p=>p.id===selected),scope=$('source').value;$('detail-team').textContent=p.team;$('detail-name').textContent=p.name+' · '+p.zh;$('detail-note').textContent=p.priority;$('detail-boundary').textContent=p.boundary;const list=DATA.assets.filter(a=>a.person===selected&&(scope==='all'||a.category===scope)).sort((a,b)=>Number(b.local===`source-assets/${p.hero}`)-Number(a.local===`source-assets/${p.hero}`)||Number(a.mirror)-Number(b.mirror));$('asset-count').textContent=`${list.length} 份资料 · 点击图片查看本地原图`;$('gallery').innerHTML=list.length?list.map(a=>`<figure class="asset" data-source-kind="${a.category}" data-sha="${a.sha256}"><a class="image-link" href="${esc(a.local)}" target="_blank" rel="noopener"><img src="${esc(a.local)}" alt="${esc(p.name+' · '+assetTitle(a))}" loading="lazy"></a><figcaption><span class="tag ${a.mirror?'mirror':''}">${a.category==='gameplay_frame'?'游戏过场 · 社区实录':a.mirror?'官方出版物 · 第三方镜像':'官网直接托管'}</span><h3>${esc(assetTitle(a))}</h3><div class="minor">${a.dimensions.join(' × ')} · ${(a.bytes/1024).toFixed(0)} KB</div><p class="description">${esc(a.visible_details||a.coverage||'')}</p><div class="links"><a href="${esc(a.local)}" target="_blank" rel="noopener">本地原图</a><a href="${esc(a.page)}" target="_blank" rel="noopener noreferrer">${a.category==='gameplay_frame'?'实录视频':a.mirror?'镜像页面':'官方来源页'} ↗</a><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">图源 ↗</a></div><details><summary>阶段、边界与来源记录</summary><p>${esc(a.appearance_phase||a.stage||'')}</p><p>${esc(a.limitations||a.identity_evidence||'')}</p><a href="${a.manifest}">查看 JSON 清单</a><code>SHA-256 ${a.sha256}</code></details></figcaption></figure>`).join(''):'<div class="empty">该人物在当前来源范围没有已收集图像。</div>';}
$('total').textContent=DATA.assets.length;$('search').addEventListener('input',drawPeople);$('team').addEventListener('change',drawPeople);$('source').addEventListener('change',drawDetail);drawPeople();drawDetail();
</script></body></html>'''.replace("__DATA__", data)
(HERE / "index.html").write_text(html, encoding="utf-8")
print(json.dumps({"characters": len(people), "unique_assets": len(assets), "source_json": SOURCES, "all_hashes_match": True, "output": str(HERE / "index.html")}, ensure_ascii=False))
